char* strsep_acados(char** stringp, const char* delim)
{
    char* result;

    if ((stringp == NULL) || (*stringp == NULL)) return NULL;

    result = *stringp;

    while (**stringp && !STD(strchr)(delim, **stringp)) ++*stringp;

    if (**stringp)
        *(*stringp)++ = '\0';
    else
        *stringp = NULL;

    return result;
}

