static std::string escape( std::string const& str ) {
    std::string escaped = str;
    replaceInPlace( escaped, "|", "||" );
    replaceInPlace( escaped, "'", "|'" );
    replaceInPlace( escaped, "\n", "|n" );
    replaceInPlace( escaped, "\r", "|r" );
    replaceInPlace( escaped, "[", "|[" );
    replaceInPlace( escaped, "]", "|]" );
    return escaped;
}

