def write_thread(self):
  try:
    with FileReader(self.fn) as f:
      while True:
        r = f.read(1024*1024)
        if len(r) == 0:
          break
        self.proc.stdin.write(r)
  except BrokenPipeError:
    pass
  finally:
    self.proc.stdin.close()

