def append_dict(path, t, d, values):
  if path not in values:
    group = {}
    group["t"] = []
    for k in d:
      group[k] = []
    values[path] = group
  else:
    group = values[path]

  group["t"].append(t)
  for k, v in d.items():
    group[k].append(v)

